        exsr SendMsgText;

    endsl;

    // Clear the option field after processing, then update the subfile row
    SFOPT = '   ';
    update MSGSFL;

    // Read next changed row
    readc MSGSFL;
    WkEof = %eof(MSGWDSPF);

  enddo;

endsr;

// ============================================================================
// Subroutine: SendMsgText
// Send WkMsgText as an immediate *INFO message to the external message queue,
// which feeds the message subfile on line 24.
// ============================================================================
begsr SendMsgText;

  // Clear the old message subfile first, then add new message.
  MsgClr = *on;
  write MSGQCTL;
  MsgClr = *off;

  SendPgmMsg(
    NullBuf :                           // No message ID (immediate)
    '                    ' :            // No message file
    %char(WkMsgText) :                  // Message text
    %len(%trimr(WkMsgText)) :           // Length of text
    '*INFO     ' :                      // Message type
    '*EXT      ' :                      // External message queue
    0 :                                 // Call stack counter
    MsgKey :                            // Returned message key
    ErrCode                             // Error code DS
  );

  MsgDsp = *on;         // Activate message subfile display indicators
  write MSGQCTL;        // Write message subfile control to show new message

endsr;

