**free
// ===========================================================================
// Program   : MSGWMON
// Source    : BOB4IPGMR/QRPGLESRC,MSGWMON  (SQLRPGLE)
// Purpose   : Real-time job monitor - displays all jobs in MSGW (Message
//             Wait) status.  Operators can take action on each listed job.
//
// Options available:
//   2 = Work With Job    (WRKJOB)
//   3 = Hold Job         (HLDJOB)
//   4 = End Job Cntrl    (ENDJOB OPTION(*CNTRLD))
//   5 = Display Messages (WRKMSG)
//   6 = Release Job      (RLSJOB)
//   7 = Display Job Log  (DSPJOBLOG)
//   8 = End Job Immed    (ENDJOB OPTION(*IMMED))
//
// Function Keys:
//   F3  = Exit
//   F5  = Refresh (re-query MSGW jobs)
//   F12 = Cancel / clear entered options
//
// Notes:
//   - Uses QSYS2.ACTIVE_JOB_INFO SQL service to retrieve MSGW jobs.
//   - Uses a message subfile (MSGQSFL/MSGQCTL) on line 24 for status msgs.
//   - Requires *JOBCTL special authority to act on other users' jobs.
//   - SFILE(MSGSFL: WkRRN) enables subfile record-format I/O operations.
//   - READC iterates changed subfile rows (rows where operator typed options).
// ===========================================================================

// ---------------------------------------------------------------------------
// Control options
// ---------------------------------------------------------------------------
ctl-opt dftactgrp(*no) actgrp(*new);
ctl-opt option(*srcstmt: *nodebugio);
ctl-opt datfmt(*iso) timfmt(*iso);

// ---------------------------------------------------------------------------
// Standalone variables required before file declaration (used in SFILE)
// ---------------------------------------------------------------------------
dcl-s WkRRN     zoned(4:0);    // Subfile RRN (must be zoned for SFILE keyword)

// ---------------------------------------------------------------------------
// File declarations
// SFILE(subfile-format : rrn-field) enables subfile record-format operations.
// ---------------------------------------------------------------------------
dcl-f MSGWDSPF workstn sfile(MSGSFL: WkRRN) indds(Ind);

// ---------------------------------------------------------------------------
// Indicator data structure  (matches INDARA in the display file)
// ---------------------------------------------------------------------------
dcl-ds Ind;
  F3Exit        ind pos(3);     // F3  = Exit
  F5Refresh     ind pos(5);     // F5  = Refresh
  F12Cancel     ind pos(12);    // F12 = Cancel
  SflDsp        ind pos(31);    // IN31 = SFLDSP
  SflDspCtl     ind pos(32);    // IN32 = SFLDSPCTL
  SflClr        ind pos(33);    // IN33 = SFLCLR (also: no-records state)
  SflEnd        ind pos(34);    // IN34 = SFLEND
  CntGrn        ind pos(35);    // IN35 = count > 0 (green), else yellow
  MsgDsp        ind pos(90);    // IN90 = SFLDSP / SFLDSPCTL for msg subfile
  MsgClr        ind pos(91);    // IN91 = SFLCLR for msg subfile
end-ds;

// ---------------------------------------------------------------------------
// Standalone variables
// ---------------------------------------------------------------------------
dcl-s WkCmd     varchar(256);   // CL command buffer for QCMDEXC
dcl-s WkCmdLen  packed(15:5);   // Length of CL command
dcl-s WkQualJob char(26);       // nnnnnnn/user/jobname for CL commands
dcl-s WkJobCnt  packed(4:0);    // Total MSGW job count
dcl-s WkMsgText varchar(100);   // Text for message subfile
dcl-s WkEof     ind;            // End-of-file flag for READC

// ---------------------------------------------------------------------------
// Prototypes
// ---------------------------------------------------------------------------
dcl-pr QCMDEXC extpgm('QCMDEXC');
  Cmd   char(32702) const;
  CLen  packed(15:5) const;
end-pr;

dcl-pr SendPgmMsg extpgm('QMHSNDPM');
  MsgId    char(7)    const;
  MsgFile  char(20)   const;
  MsgData  char(256)  const;
  MsgDLen  int(10)    const;
  MsgType  char(10)   const;
  CallStkE char(10)   const;
  CallStkC int(10)    const;
  MsgKey   char(4);
  ErrCode  char(256);
end-pr;

// ---------------------------------------------------------------------------
// Host variables for the SQL cursor
// ---------------------------------------------------------------------------
dcl-ds JobRow qualified;
  JobName   varchar(28);
  JobUser   varchar(10);
  JobNumber varchar(6);
  JobType   varchar(3);
  Subsystem varchar(10);
  FuncType  varchar(2);
  Function  varchar(10);
end-ds;

// ---------------------------------------------------------------------------
// Miscellaneous working variables
// ---------------------------------------------------------------------------
dcl-s MsgKey   char(4);           // Message key returned by QMHSNDPM
dcl-s ErrCode  char(256) inz;     // Error code buffer (QMHSNDPM)
dcl-s NullBuf  char(7)   inz;     // Blank – immediate msg has no msg id

// ============================================================================
// Mainline
// ============================================================================

// Show the footer (function key legend) once - it uses OVERLAY so it stays.
write FOOTER;

// Display refresh loop: stays until F3 Exit.
dou F3Exit;

  // Load the subfile with current MSGW jobs.
  exsr LoadSubfile;

  // Display the subfile control (header + list) and wait for operator input.
  exfmt MSGCTL;

  // Check function keys first.
  if F3Exit;
    leave;
  endif;

  if F5Refresh;
    iter;           // Loop back to reload subfile
  endif;

  if F12Cancel;
    iter;           // Clear any entries, re-display
  endif;

  // Process entered options using READC (changed subfile rows only).
  exsr ProcessOptions;

enddo;

// Clear message subfile on exit.
MsgClr = *on;
write MSGQCTL;
MsgClr = *off;

*inlr = *on;
return;

// ============================================================================
// Subroutine: LoadSubfile
// Clear and rebuild the subfile from QSYS2.ACTIVE_JOB_INFO.
// ============================================================================
begsr LoadSubfile;

  // --- Clear the subfile ---
  SflDsp    = *off;
  SflDspCtl = *off;
  SflClr    = *on;
  SflEnd    = *off;
  CntGrn    = *off;
  CTJOBCNT  = 0;
  write MSGCTL;
  SflClr    = *off;

  // --- Also clear message subfile ---
  MsgClr = *on;
  write MSGQCTL;
  MsgClr = *off;
  MsgDsp = *off;

  // --- Query MSGW jobs via SQL cursor ---
  WkJobCnt = 0;
  WkRRN    = 0;

  exec sql
    DECLARE C_MSGWJOBS CURSOR FOR
      SELECT
        JOB_NAME,
        JOB_USER,
        JOB_NUMBER,
        COALESCE(JOB_TYPE,      '   '),
        COALESCE(SUBSYSTEM,     '          '),
        COALESCE(FUNCTION_TYPE, '  '),
        COALESCE(FUNCTION,      '          ')
      FROM TABLE(QSYS2.ACTIVE_JOB_INFO())
      WHERE JOB_STATUS = 'MSGW'
      ORDER BY JOB_TYPE, SUBSYSTEM, JOB_USER, JOB_NAME;

  exec sql OPEN C_MSGWJOBS;

  if SQLCODE < 0;
    WkMsgText = 'SQL error (SQLCODE=' + %char(SQLCODE) +
                ') querying ACTIVE_JOB_INFO.';
    exsr SendMsgText;
  else;

    exec sql
      FETCH NEXT FROM C_MSGWJOBS
      INTO :JobRow.JobName,   :JobRow.JobUser,   :JobRow.JobNumber,
           :JobRow.JobType,   :JobRow.Subsystem,
           :JobRow.FuncType,  :JobRow.Function;

    dow SQLCODE = 0;
      WkJobCnt += 1;
      WkRRN    += 1;

      // Populate subfile output fields
      SFOPT      = '   ';
      SFJOBNUM   = %char(JobRow.JobNumber);
      SFJOBUSR   = %char(JobRow.JobUser);
      SFJOBNAM   = %char(JobRow.JobName);
      SFJOBTYP   = %char(JobRow.JobType);
      SFSUBSYS   = %char(JobRow.Subsystem);
      SFTYPE     = %char(JobRow.FuncType);
      SFFUNCTION = %char(JobRow.Function);
      // Qualified job name stored in hidden field: number/user/name
      SFQJOB     = %trimr(%char(JobRow.JobNumber)) + '/' +
                   %trimr(%char(JobRow.JobUser))   + '/' +
                   %trimr(%char(JobRow.JobName));

      write MSGSFL;

      exec sql
        FETCH NEXT FROM C_MSGWJOBS
        INTO :JobRow.JobName,   :JobRow.JobUser,   :JobRow.JobNumber,
             :JobRow.JobType,   :JobRow.Subsystem,
             :JobRow.FuncType,  :JobRow.Function;
    enddo;

    exec sql CLOSE C_MSGWJOBS;

    // If no jobs found, send informational message to message subfile
    if WkJobCnt = 0;
      WkMsgText = 'No jobs currently in MSGW status. Press F5 to refresh.';
      exsr SendMsgText;
    endif;

  endif;

  // --- Set subfile display indicators ---
  CTJOBCNT  = WkJobCnt;
  CntGrn    = (WkJobCnt > 0);     // Green when jobs found, yellow otherwise
  SflDsp    = (WkJobCnt > 0);     // Show subfile only when records exist
  SflDspCtl = *on;
  SflClr    = (WkJobCnt = 0);     // Write SFLCLR when empty (SFLSIZ requires it)
  SflEnd    = *on;

endsr;

// ============================================================================
// Subroutine: ProcessOptions
// Use READC to iterate only the subfile rows where the operator typed an
// option, and execute the requested action for each.
// ============================================================================
begsr ProcessOptions;

  WkEof = *off;

  readc MSGSFL;
  WkEof = %eof(MSGWDSPF);

  dow not WkEof;

    // Skip blank options
    if %trim(SFOPT) = '';
      readc MSGSFL;
      WkEof = %eof(MSGWDSPF);
      iter;
    endif;

    WkQualJob = SFQJOB;

    select;

      // 2 = Work With Job
      when %trim(SFOPT) = '2';
        WkCmd    = 'WRKJOB JOB(' + %trimr(WkQualJob) + ')';
        WkCmdLen = %len(%trimr(WkCmd));
        QCMDEXC(WkCmd: WkCmdLen);

      // 3 = Hold Job
      when %trim(SFOPT) = '3';
        WkCmd    = 'HLDJOB JOB(' + %trimr(WkQualJob) + ') DUPJOBOPT(*MSG)';
        WkCmdLen = %len(%trimr(WkCmd));
        monitor;
          QCMDEXC(WkCmd: WkCmdLen);
          WkMsgText = 'Hold submitted for: ' + %trimr(WkQualJob);
          exsr SendMsgText;
        on-error;
          WkMsgText = 'Hold failed for: ' + %trimr(WkQualJob) +
                      '. Check job log.';
          exsr SendMsgText;
        endmon;

      // 4 = End Job (Controlled)
      when %trim(SFOPT) = '4';
        WkCmd    = 'ENDJOB JOB(' + %trimr(WkQualJob) +
                   ') OPTION(*CNTRLD) DELAY(30) DUPJOBOPT(*MSG)';
        WkCmdLen = %len(%trimr(WkCmd));
        monitor;
          QCMDEXC(WkCmd: WkCmdLen);
          WkMsgText = 'End (Ctrl) submitted for: ' + %trimr(WkQualJob);
          exsr SendMsgText;
        on-error;
          WkMsgText = 'End (Ctrl) failed for: ' + %trimr(WkQualJob) +
                      '. Check job log.';
          exsr SendMsgText;
        endmon;

      // 5 = Display Messages
      when %trim(SFOPT) = '5';
        WkCmd    = 'WRKMSG JOB(' + %trimr(WkQualJob) + ')';
        WkCmdLen = %len(%trimr(WkCmd));
        QCMDEXC(WkCmd: WkCmdLen);

      // 6 = Release Job
      when %trim(SFOPT) = '6';
        WkCmd    = 'RLSJOB JOB(' + %trimr(WkQualJob) + ') DUPJOBOPT(*MSG)';
        WkCmdLen = %len(%trimr(WkCmd));
        monitor;
          QCMDEXC(WkCmd: WkCmdLen);
          WkMsgText = 'Release submitted for: ' + %trimr(WkQualJob);
          exsr SendMsgText;
        on-error;
          WkMsgText = 'Release failed for: ' + %trimr(WkQualJob) +
                      '. Check job log.';
          exsr SendMsgText;
        endmon;

      // 7 = Display Job Log
      when %trim(SFOPT) = '7';
        WkCmd    = 'DSPJOBLOG JOB(' + %trimr(WkQualJob) + ') OUTPUT(*)';
        WkCmdLen = %len(%trimr(WkCmd));
        QCMDEXC(WkCmd: WkCmdLen);

      // 8 = End Job (Immediate)
      when %trim(SFOPT) = '8';
        WkCmd    = 'ENDJOB JOB(' + %trimr(WkQualJob) +
                   ') OPTION(*IMMED) DUPJOBOPT(*MSG)';
        WkCmdLen = %len(%trimr(WkCmd));
        monitor;
          QCMDEXC(WkCmd: WkCmdLen);
          WkMsgText = 'End (Immed) submitted for: ' + %trimr(WkQualJob);
          exsr SendMsgText;
        on-error;
          WkMsgText = 'End (Immed) failed for: ' + %trimr(WkQualJob) +
                      '. Check job log.';
          exsr SendMsgText;
        endmon;

      // Unknown option
      other;
        WkMsgText = 'Option "' + %trimr(SFOPT) +
                    '" not valid. Use 2, 3, 4, 5, 6, 7, or 8.';
        exsr SendMsgText;

    endsl;

    // Clear the option field after processing, then update the subfile row
    SFOPT = '   ';
    update MSGSFL;

    // Read next changed row
    readc MSGSFL;
    WkEof = %eof(MSGWDSPF);

  enddo;

endsr;

// ============================================================================
// Subroutine: SendMsgText
// Send WkMsgText as an immediate *INFO message to the external message queue,
// which feeds the message subfile on line 24.
// ============================================================================
begsr SendMsgText;

  // Clear the old message subfile first, then add new message.
  MsgClr = *on;
  write MSGQCTL;
  MsgClr = *off;

  SendPgmMsg(
    NullBuf :                           // No message ID (immediate)
    '                    ' :            // No message file
    %char(WkMsgText) :                  // Message text
    %len(%trimr(WkMsgText)) :           // Length of text
    '*INFO     ' :                      // Message type
    '*EXT      ' :                      // External message queue
    0 :                                 // Call stack counter
    MsgKey :                            // Returned message key
    ErrCode                             // Error code DS
  );

  MsgDsp = *on;         // Activate message subfile display indicators
  write MSGQCTL;        // Write message subfile control to show new message

endsr;

**free
// ===========================================================================
// Program   : MSGWMON
// Source    : BOB4IPGMR/QRPGLESRC,MSGWMON  (SQLRPGLE)
// Purpose   : Real-time job monitor - displays all jobs in MSGW (Message
//             Wait) status.  Operators can take action on each listed job.
//
// Options available:
//   2 = Work With Job    (WRKJOB)
//   3 = Hold Job         (HLDJOB)
//   4 = End Job Cntrl    (ENDJOB OPTION(*CNTRLD))
//   5 = Display Messages (WRKMSG)
//   6 = Release Job      (RLSJOB)
//   7 = Display Job Log  (DSPJOBLOG)
//   8 = End Job Immed    (ENDJOB OPTION(*IMMED))
//
// Function Keys:
//   F3  = Exit
//   F5  = Refresh (re-query MSGW jobs)
//   F12 = Cancel / clear entered options
//
// Notes:
//   - Uses QSYS2.ACTIVE_JOB_INFO SQL service to retrieve MSGW jobs.
//   - Uses a message subfile (MSGQSFL/MSGQCTL) on line 24 for status msgs.
//   - Requires *JOBCTL special authority to act on other users' jobs.
//   - SFILE(MSGSFL: WkRRN) enables subfile record-format I/O operations.
//   - READC iterates changed subfile rows (rows where operator typed options).
// ===========================================================================

// ---------------------------------------------------------------------------
// Control options
// ---------------------------------------------------------------------------
ctl-opt dftactgrp(*no) actgrp(*new);
ctl-opt option(*srcstmt: *nodebugio);
ctl-opt datfmt(*iso) timfmt(*iso);

// ---------------------------------------------------------------------------
// Standalone variables required before file declaration (used in SFILE)
// ---------------------------------------------------------------------------
dcl-s WkRRN     zoned(4:0);    // Subfile RRN (must be zoned for SFILE keyword)

// ---------------------------------------------------------------------------
// File declarations
// SFILE(subfile-format : rrn-field) enables subfile record-format operations.
// ---------------------------------------------------------------------------
dcl-f MSGWDSPF workstn sfile(MSGSFL: WkRRN) indds(Ind);

// ---------------------------------------------------------------------------
// Indicator data structure  (matches INDARA in the display file)
// ---------------------------------------------------------------------------
dcl-ds Ind;
  F3Exit        ind pos(3);     // F3  = Exit
  F5Refresh     ind pos(5);     // F5  = Refresh
  F12Cancel     ind pos(12);    // F12 = Cancel
  SflDsp        ind pos(31);    // IN31 = SFLDSP
  SflDspCtl     ind pos(32);    // IN32 = SFLDSPCTL
  SflClr        ind pos(33);    // IN33 = SFLCLR (also: no-records state)
  SflEnd        ind pos(34);    // IN34 = SFLEND
  CntGrn        ind pos(35);    // IN35 = count > 0 (green), else yellow
  MsgDsp        ind pos(90);    // IN90 = SFLDSP / SFLDSPCTL for msg subfile
  MsgClr        ind pos(91);    // IN91 = SFLCLR for msg subfile
end-ds;

// ---------------------------------------------------------------------------
// Standalone variables
// ---------------------------------------------------------------------------
dcl-s WkCmd     varchar(256);   // CL command buffer for QCMDEXC
dcl-s WkCmdLen  packed(15:5);   // Length of CL command
dcl-s WkQualJob char(26);       // nnnnnnn/user/jobname for CL commands
dcl-s WkJobCnt  packed(4:0);    // Total MSGW job count
dcl-s WkMsgText varchar(100);   // Text for message subfile
dcl-s WkEof     ind;            // End-of-file flag for READC

// ---------------------------------------------------------------------------
// Prototypes
// ---------------------------------------------------------------------------
dcl-pr QCMDEXC extpgm('QCMDEXC');
  Cmd   char(32702) const;
  CLen  packed(15:5) const;
end-pr;

dcl-pr SendPgmMsg extpgm('QMHSNDPM');
  MsgId    char(7)    const;
  MsgFile  char(20)   const;
  MsgData  char(256)  const;
  MsgDLen  int(10)    const;
  MsgType  char(10)   const;
  CallStkE char(10)   const;
  CallStkC int(10)    const;
  MsgKey   char(4);
  ErrCode  char(256);
end-pr;

// ---------------------------------------------------------------------------
// Host variables for the SQL cursor
// ---------------------------------------------------------------------------
dcl-ds JobRow qualified;
  JobName   varchar(28);
  JobUser   varchar(10);
  JobNumber varchar(6);
  JobType   varchar(3);
  Subsystem varchar(10);
  FuncType  varchar(2);
  Function  varchar(10);
end-ds;

// ---------------------------------------------------------------------------
// Miscellaneous working variables
// ---------------------------------------------------------------------------
dcl-s MsgKey   char(4);           // Message key returned by QMHSNDPM
dcl-s ErrCode  char(256) inz;     // Error code buffer (QMHSNDPM)
dcl-s NullBuf  char(7)   inz;     // Blank – immediate msg has no msg id

// ============================================================================
// Mainline
// ============================================================================

// Show the footer (function key legend) once - it uses OVERLAY so it stays.
write FOOTER;

// Display refresh loop: stays until F3 Exit.
dou F3Exit;

  // Load the subfile with current MSGW jobs.
  exsr LoadSubfile;

  // Display the subfile control (header + list) and wait for operator input.
  exfmt MSGCTL;

  // Check function keys first.
  if F3Exit;
    leave;
  endif;

  if F5Refresh;
    iter;           // Loop back to reload subfile
  endif;

  if F12Cancel;
    iter;           // Clear any entries, re-display
  endif;

  // Process entered options using READC (changed subfile rows only).
  exsr ProcessOptions;

enddo;

// Clear message subfile on exit.
MsgClr = *on;
write MSGQCTL;
MsgClr = *off;

*inlr = *on;
return;

// ============================================================================
// Subroutine: LoadSubfile
// Clear and rebuild the subfile from QSYS2.ACTIVE_JOB_INFO.
// ============================================================================
begsr LoadSubfile;

  // --- Clear the subfile ---
  SflDsp    = *off;
  SflDspCtl = *off;
  SflClr    = *on;
  SflEnd    = *off;
  CntGrn    = *off;
  CTJOBCNT  = 0;
  write MSGCTL;
  SflClr    = *off;

  // --- Also clear message subfile ---
  MsgClr = *on;
  write MSGQCTL;
  MsgClr = *off;
  MsgDsp = *off;

  // --- Query MSGW jobs via SQL cursor ---
  WkJobCnt = 0;
  WkRRN    = 0;

  exec sql
    DECLARE C_MSGWJOBS CURSOR FOR
      SELECT
        JOB_NAME,
        JOB_USER,
        JOB_NUMBER,
        COALESCE(JOB_TYPE,      '   '),
        COALESCE(SUBSYSTEM,     '          '),
        COALESCE(FUNCTION_TYPE, '  '),
        COALESCE(FUNCTION,      '          ')
      FROM TABLE(QSYS2.ACTIVE_JOB_INFO())
      WHERE JOB_STATUS = 'MSGW'
      ORDER BY JOB_TYPE, SUBSYSTEM, JOB_USER, JOB_NAME;

  exec sql OPEN C_MSGWJOBS;

  if SQLCODE < 0;
    WkMsgText = 'SQL error (SQLCODE=' + %char(SQLCODE) +
                ') querying ACTIVE_JOB_INFO.';
    exsr SendMsgText;
  else;

    exec sql
      FETCH NEXT FROM C_MSGWJOBS
      INTO :JobRow.JobName,   :JobRow.JobUser,   :JobRow.JobNumber,
           :JobRow.JobType,   :JobRow.Subsystem,
           :JobRow.FuncType,  :JobRow.Function;

    dow SQLCODE = 0;
      WkJobCnt += 1;
      WkRRN    += 1;

      // Populate subfile output fields
      SFOPT      = '   ';
      SFJOBNUM   = %char(JobRow.JobNumber);
      SFJOBUSR   = %char(JobRow.JobUser);
      SFJOBNAM   = %char(JobRow.JobName);
      SFJOBTYP   = %char(JobRow.JobType);
      SFSUBSYS   = %char(JobRow.Subsystem);
      SFTYPE     = %char(JobRow.FuncType);
      SFFUNCTION = %char(JobRow.Function);
      // Qualified job name stored in hidden field: number/user/name
      SFQJOB     = %trimr(%char(JobRow.JobNumber)) + '/' +
                   %trimr(%char(JobRow.JobUser))   + '/' +
                   %trimr(%char(JobRow.JobName));

      write MSGSFL;

      exec sql
        FETCH NEXT FROM C_MSGWJOBS
        INTO :JobRow.JobName,   :JobRow.JobUser,   :JobRow.JobNumber,
             :JobRow.JobType,   :JobRow.Subsystem,
             :JobRow.FuncType,  :JobRow.Function;
    enddo;

    exec sql CLOSE C_MSGWJOBS;

    // If no jobs found, send informational message to message subfile
    if WkJobCnt = 0;
      WkMsgText = 'No jobs currently in MSGW status. Press F5 to refresh.';
      exsr SendMsgText;
    endif;

  endif;

  // --- Set subfile display indicators ---
  CTJOBCNT  = WkJobCnt;
  CntGrn    = (WkJobCnt > 0);     // Green when jobs found, yellow otherwise
  SflDsp    = (WkJobCnt > 0);     // Show subfile only when records exist
  SflDspCtl = *on;
  SflClr    = (WkJobCnt = 0);     // Write SFLCLR when empty (SFLSIZ requires it)
  SflEnd    = *on;

endsr;

// ============================================================================
// Subroutine: ProcessOptions
// Use READC to iterate only the subfile rows where the operator typed an
// option, and execute the requested action for each.
// ============================================================================
begsr ProcessOptions;

  WkEof = *off;

  readc MSGSFL;
  WkEof = %eof(MSGWDSPF);

  dow not WkEof;

    // Skip blank options
    if %trim(SFOPT) = '';
      readc MSGSFL;
      WkEof = %eof(MSGWDSPF);
      iter;
    endif;

    WkQualJob = SFQJOB;

    select;

      // 2 = Work With Job
      when %trim(SFOPT) = '2';
        WkCmd    = 'WRKJOB JOB(' + %trimr(WkQualJob) + ')';
        WkCmdLen = %len(%trimr(WkCmd));
        QCMDEXC(WkCmd: WkCmdLen);

      // 3 = Hold Job
      when %trim(SFOPT) = '3';
        WkCmd    = 'HLDJOB JOB(' + %trimr(WkQualJob) + ') DUPJOBOPT(*MSG)';
        WkCmdLen = %len(%trimr(WkCmd));
        monitor;
          QCMDEXC(WkCmd: WkCmdLen);
          WkMsgText = 'Hold submitted for: ' + %trimr(WkQualJob);
          exsr SendMsgText;
        on-error;
          WkMsgText = 'Hold failed for: ' + %trimr(WkQualJob) +
                      '. Check job log.';
          exsr SendMsgText;
        endmon;

      // 4 = End Job (Controlled)
      when %trim(SFOPT) = '4';
        WkCmd    = 'ENDJOB JOB(' + %trimr(WkQualJob) +
                   ') OPTION(*CNTRLD) DELAY(30) DUPJOBOPT(*MSG)';
        WkCmdLen = %len(%trimr(WkCmd));
        monitor;
          QCMDEXC(WkCmd: WkCmdLen);
          WkMsgText = 'End (Ctrl) submitted for: ' + %trimr(WkQualJob);
          exsr SendMsgText;
        on-error;
          WkMsgText = 'End (Ctrl) failed for: ' + %trimr(WkQualJob) +
                      '. Check job log.';
          exsr SendMsgText;
        endmon;

      // 5 = Display Messages
      when %trim(SFOPT) = '5';
        WkCmd    = 'WRKMSG JOB(' + %trimr(WkQualJob) + ')';
        WkCmdLen = %len(%trimr(WkCmd));
        QCMDEXC(WkCmd: WkCmdLen);

      // 6 = Release Job
      when %trim(SFOPT) = '6';
        WkCmd    = 'RLSJOB JOB(' + %trimr(WkQualJob) + ') DUPJOBOPT(*MSG)';
        WkCmdLen = %len(%trimr(WkCmd));
        monitor;
          QCMDEXC(WkCmd: WkCmdLen);
          WkMsgText = 'Release submitted for: ' + %trimr(WkQualJob);
          exsr SendMsgText;
        on-error;
          WkMsgText = 'Release failed for: ' + %trimr(WkQualJob) +
                      '. Check job log.';
          exsr SendMsgText;
        endmon;

      // 7 = Display Job Log
      when %trim(SFOPT) = '7';
        WkCmd    = 'DSPJOBLOG JOB(' + %trimr(WkQualJob) + ') OUTPUT(*)';
        WkCmdLen = %len(%trimr(WkCmd));
        QCMDEXC(WkCmd: WkCmdLen);

      // 8 = End Job (Immediate)
      when %trim(SFOPT) = '8';
        WkCmd    = 'ENDJOB JOB(' + %trimr(WkQualJob) +
                   ') OPTION(*IMMED) DUPJOBOPT(*MSG)';
        WkCmdLen = %len(%trimr(WkCmd));
        monitor;
          QCMDEXC(WkCmd: WkCmdLen);
          WkMsgText = 'End (Immed) submitted for: ' + %trimr(WkQualJob);
          exsr SendMsgText;
        on-error;
          WkMsgText = 'End (Immed) failed for: ' + %trimr(WkQualJob) +
                      '. Check job log.';
          exsr SendMsgText;
        endmon;

      // Unknown option
      other;
        WkMsgText = 'Option "' + %trimr(SFOPT) +
                    '" not valid. Use 2, 3, 4, 5, 6, 7, or 8.';
        exsr SendMsgText;

    endsl;

    // Clear the option field after processing, then update the subfile row
    SFOPT = '   ';
    update MSGSFL;

    // Read next changed row
    readc MSGSFL;
    WkEof = %eof(MSGWDSPF);

  enddo;

endsr;

// ============================================================================
// Subroutine: SendMsgText
// Send WkMsgText as an immediate *INFO message to the external message queue,
// which feeds the message subfile on line 24.
// ============================================================================
begsr SendMsgText;

  // Clear the old message subfile first, then add new message.
  MsgClr = *on;
  write MSGQCTL;
  MsgClr = *off;

  SendPgmMsg(
    NullBuf :                           // No message ID (immediate)
    '                    ' :            // No message file
    %char(WkMsgText) :                  // Message text
    %len(%trimr(WkMsgText)) :           // Length of text
    '*INFO     ' :                      // Message type
    '*EXT      ' :                      // External message queue
    0 :                                 // Call stack counter
    MsgKey :                            // Returned message key
    ErrCode                             // Error code DS
  );

  MsgDsp = *on;         // Activate message subfile display indicators
  write MSGQCTL;        // Write message subfile control to show new message

endsr;

