data.content:
/BOB4IPGMR/QRPGLESRC/MSGWMON.SQLRPGLE:
  1 | **free
  2 | // ===========================================================================
  3 | // Program   : MSGWMON
  4 | // Source    : BOB4IPGMR/QRPGLESRC,MSGWMON  (SQLRPGLE)
  5 | // Purpose   : Real-time job monitor - displays all jobs in MSGW (Message
  6 | //             Wait) status.  Operators can take action on each listed job.
  7 | //
  8 | // Options available:
  9 | //   2 = Work With Job    (WRKJOB)
 10 | //   3 = Hold Job         (HLDJOB)
 11 | //   4 = End Job Cntrl    (ENDJOB OPTION(*CNTRLD))
 12 | //   5 = Display Messages (WRKJOB OPTION(*MSG))
 13 | //   6 = Release Job      (RLSJOB)
 14 | //   7 = Display Job Log  (DSPJOBLOG)
 15 | //   8 = End Job Immed    (ENDJOB OPTION(*IMMED))
 16 | //
 17 | // Function Keys:
 18 | //   F3  = Exit  |  F5 = Refresh  |  F12 = Cancel
 19 | //
 20 | // Notes:
 21 | //   - ACTIVE_JOB_INFO.JOB_NAME is the full qualified name (number/user/name).
 22 | //     SFQJOB is assigned directly from it; SUBSTR extracts the short name.
 23 | //   - QCMDEXC Cmd parameter is char OPTIONS(*VARSIZE) per IBM documentation.
 24 | //     Passing varchar to a char CONST parameter works via auto-conversion.
 25 | //     Using varchar(32702) caused the 2-byte length prefix to appear as two
 26 | //     leading spaces in the command string, producing 'invalid character' errors.
 27 | // ===========================================================================
 28 | 
 29 | // ---------------------------------------------------------------------------
 30 | // Control options
 31 | // ---------------------------------------------------------------------------
 32 | ctl-opt dftactgrp(*no) actgrp(*new);
 33 | ctl-opt option(*srcstmt: *nodebugio);
 34 | ctl-opt datfmt(*iso) timfmt(*iso);
 35 | 
 36 | // ---------------------------------------------------------------------------
 37 | // Standalone variables required before file declaration (used in SFILE)
 38 | // ---------------------------------------------------------------------------
 39 | dcl-s WkRRN     zoned(4:0);    // Subfile RRN (zoned required by SFILE keyword)
 40 | 
 41 | // ---------------------------------------------------------------------------
 42 | // File declarations
 43 | // ---------------------------------------------------------------------------
 44 | dcl-f MSGWDSPF workstn sfile(MSGSFL: WkRRN) indds(Ind);
 45 | 
 46 | // ---------------------------------------------------------------------------
 47 | // Indicator data structure
 48 | // ---------------------------------------------------------------------------
 49 | dcl-ds Ind;
 50 |   F3Exit        ind pos(3);
 51 |   F5Refresh     ind pos(5);
 52 |   F12Cancel     ind pos(12);
 53 |   SflDsp        ind pos(31);
 54 |   SflDspCtl     ind pos(32);
 55 |   SflClr        ind pos(33);
 56 |   SflEnd        ind pos(34);
 57 |   CntGrn        ind pos(35);
 58 |   MsgDsp        ind pos(90);
 59 |   MsgClr        ind pos(91);
 60 | end-ds;
 61 | 
 62 | // ---------------------------------------------------------------------------
 63 | // Standalone variables
 64 | // ---------------------------------------------------------------------------
 65 | dcl-s WkCmd     varchar(512);
 66 | dcl-s WkCmdLen  packed(15:5);
 67 | dcl-s WkQualJob varchar(28);
 68 | dcl-s WkJobCnt  packed(4:0);
 69 | dcl-s WkMsgText varchar(100);
 70 | dcl-s WkEof     ind;
 71 | 
 72 | // ---------------------------------------------------------------------------
 73 | // Prototypes
 74 | // ---------------------------------------------------------------------------
 75 | // QCMDEXC: Cmd MUST be char OPTIONS(*VARSIZE), NOT varchar.
 76 | // Passing varchar to varchar(*VARSIZE) sends the internal 2-byte length
 77 | // prefix as part of the data  causing 'invalid character' command errors.
 78 | // With char OPTIONS(*VARSIZE) + CONST, RPG auto-converts the varchar WkCmd
 79 | // and passes exactly %len(WkCmd) bytes of clean character data.
 80 | dcl-pr QCMDEXC extpgm('QCMDEXC');
 81 |   Cmd     char(32702) options(*varsize) const;   // char  NOT varchar
 82 |   CmdLen  packed(15:5)                 const;
 83 | end-pr;
 84 | 
 85 | dcl-pr SendPgmMsg extpgm('QMHSNDPM');
 86 |   MsgId    char(7)    const;
 87 |   MsgFile  char(20)   const;
 88 |   MsgData  char(256)  const;
 89 |   MsgDLen  int(10)    const;
 90 |   MsgType  char(10)   const;
 91 |   CallStkE char(10)   const;
 92 |   CallStkC int(10)    const;
 93 |   MsgKey   char(4);
 94 |   ErrCode  char(256);
 95 | end-pr;
 96 | 
 97 | // ---------------------------------------------------------------------------
 98 | // Host variables for the SQL cursor
 99 | // ---------------------------------------------------------------------------
100 | dcl-ds JobRow qualified;
101 |   // JOB_NAME from ACTIVE_JOB_INFO is already 'number/user/name' (28 chars).
102 |   JobName      varchar(28);
103 |   // Extracted short name (after second slash)  used for display only.
104 |   JobShortName varchar(10);
105 |   JobUser      varchar(10);
106 |   JobNumber    varchar(6);
107 |   JobType      varchar(3);
108 |   Subsystem    varchar(10);
109 |   FuncType     varchar(2);
110 |   Function     varchar(10);
111 | end-ds;
112 | 
113 | // ---------------------------------------------------------------------------
114 | // Miscellaneous working variables
115 | // ---------------------------------------------------------------------------
116 | dcl-s MsgKey   char(4);
117 | dcl-s ErrCode  char(256) inz;
118 | dcl-s NullBuf  char(7)   inz;
119 | 
120 | // ============================================================================
121 | // Mainline
122 | // ============================================================================
123 | 
124 | write FOOTER;
125 | 
126 | dou F3Exit;
127 | 
128 |   exsr LoadSubfile;
129 | 
130 |   exfmt MSGCTL;
131 | 
132 |   if F3Exit;
133 |     leave;
134 |   endif;
135 | 
136 |   if F5Refresh or F12Cancel;
137 |     iter;
138 |   endif;
139 | 
140 |   exsr ProcessOptions;
141 | 
142 | enddo;
143 | 
144 | MsgClr = *on;
145 | write MSGQCTL;
146 | MsgClr = *off;
147 | 
148 | *inlr = *on;
149 | return;
150 | 
151 | // ============================================================================
152 | // Subroutine: LoadSubfile
153 | // ============================================================================
154 | begsr LoadSubfile;
155 | 
156 |   SflDsp    = *off;
157 |   SflDspCtl = *off;
158 |   SflClr    = *on;
159 |   SflEnd    = *off;
160 |   CntGrn    = *off;
161 |   CTJOBCNT  = 0;
162 |   write MSGCTL;
163 |   SflClr    = *off;
164 | 
165 |   MsgClr = *on;
166 |   write MSGQCTL;
167 |   MsgClr = *off;
168 |   MsgDsp = *off;
169 | 
170 |   WkJobCnt = 0;
171 |   WkRRN    = 0;
172 | 
173 |   exec sql
174 |     DECLARE C_MSGWJOBS CURSOR FOR
175 |       SELECT
176 |         -- JOB_NAME is the full qualified name: 'number/user/name'
177 |         JOB_NAME,
178 |         -- Extract short job name (everything after the second '/')
179 |         SUBSTR(JOB_NAME,
180 |                LOCATE('/', JOB_NAME, LOCATE('/', JOB_NAME) + 1) + 1)
181 |           AS JOB_NAME_SHORT,
182 |         JOB_USER,
183 |         JOB_NUMBER,
184 |         COALESCE(JOB_TYPE,      '   '),
185 |         COALESCE(SUBSYSTEM,     '          '),
186 |         COALESCE(FUNCTION_TYPE, '  '),
187 |         COALESCE(FUNCTION,      '          ')
188 |       FROM TABLE(QSYS2.ACTIVE_JOB_INFO())
189 |       WHERE JOB_STATUS = 'MSGW'
190 |       ORDER BY JOB_TYPE, SUBSYSTEM, JOB_USER, JOB_NAME;
191 | 
192 |   exec sql OPEN C_MSGWJOBS;
193 | 
194 |   if SQLCODE < 0;
195 |     WkMsgText = 'SQL error (SQLCODE=' + %char(SQLCODE) + ').';
196 |     exsr SendMsgText;
197 |   else;
198 | 
199 |     exec sql
200 |       FETCH NEXT FROM C_MSGWJOBS
201 |       INTO :JobRow.JobName,  :JobRow.JobShortName,
202 |            :JobRow.JobUser,  :JobRow.JobNumber,
203 |            :JobRow.JobType,  :JobRow.Subsystem,
204 |            :JobRow.FuncType, :JobRow.Function;
205 | 
206 |     dow SQLCODE = 0;
207 |       WkJobCnt += 1;
208 |       WkRRN    += 1;
209 | 
210 |       SFOPT      = '   ';
211 |       SFJOBNUM   = %char(JobRow.JobNumber);
212 |       SFJOBUSR   = %char(JobRow.JobUser);
213 |       // JobShortName is the short job name only (e.g. ORDPROC)
214 |       SFJOBNAM   = %char(JobRow.JobShortName);
215 |       SFJOBTYP   = %char(JobRow.JobType);
216 |       SFSUBSYS   = %char(JobRow.Subsystem);
217 |       SFTYPE     = %char(JobRow.FuncType);
218 |       SFFUNCTION = %char(JobRow.Function);
219 |       // JOB_NAME is already 'number/user/name'  store directly in hidden field
220 |       SFQJOB     = %char(JobRow.JobName);
221 | 
222 |       write MSGSFL;
223 | 
224 |       exec sql
225 |         FETCH NEXT FROM C_MSGWJOBS
226 |         INTO :JobRow.JobName,  :JobRow.JobShortName,
227 |              :JobRow.JobUser,  :JobRow.JobNumber,
228 |              :JobRow.JobType,  :JobRow.Subsystem,
229 |              :JobRow.FuncType, :JobRow.Function;
230 |     enddo;
231 | 
232 |     exec sql CLOSE C_MSGWJOBS;
233 | 
234 |     if WkJobCnt = 0;
235 |       WkMsgText = 'No jobs currently in MSGW status. Press F5 to refresh.';
236 |       exsr SendMsgText;
237 |     endif;
238 | 
239 |   endif;
240 | 
241 |   CTJOBCNT  = WkJobCnt;
242 |   CntGrn    = (WkJobCnt > 0);
243 |   SflDsp    = (WkJobCnt > 0);
244 |   SflDspCtl = *on;
245 |   SflClr    = (WkJobCnt = 0);
246 |   SflEnd    = *on;
247 | 
248 | endsr;
249 | 
250 | // ============================================================================
251 | // Subroutine: ProcessOptions
252 | // READC reads only subfile rows the operator modified (typed an option).
253 | // WkQualJob is varchar  no trailing-space issues when building CL commands.
254 | // ============================================================================
255 | begsr ProcessOptions;
256 | 
257 |   WkEof = *off;
258 |   readc MSGSFL;
259 |   WkEof = %eof(MSGWDSPF);
260 | 
261 |   dow not WkEof;
262 | 
263 |     if %trim(SFOPT) = '';
264 |       readc MSGSFL;
265 |       WkEof = %eof(MSGWDSPF);
266 |       iter;
267 |     endif;
268 | 
269 |     // SFQJOB is char(28); %trimr strips trailing spaces before assigning to varchar
270 |     WkQualJob = %trimr(SFQJOB);
271 | 
272 |     select;
273 | 
274 |       // 2 = Work With Job
275 |       when %trim(SFOPT) = '2';
276 |         WkCmd    = 'WRKJOB JOB(' + WkQualJob + ')';
277 |         WkCmdLen = %len(WkCmd);
278 |         QCMDEXC(WkCmd: WkCmdLen);
279 | 
280 |       // 3 = Hold Job
281 |       when %trim(SFOPT) = '3';
282 |         WkCmd    = 'HLDJOB JOB(' + WkQualJob + ') DUPJOBOPT(*MSG)';
283 |         WkCmdLen = %len(WkCmd);
284 |         monitor;
285 |           QCMDEXC(WkCmd: WkCmdLen);
286 |           WkMsgText = 'Hold submitted: ' + WkQualJob;
287 |           exsr SendMsgText;
288 |         on-error;
289 |           WkMsgText = 'Hold failed: ' + WkQualJob + '. Check job log.';
290 |           exsr SendMsgText;
291 |         endmon;
292 | 
293 |       // 4 = End Job (Controlled)
294 |       when %trim(SFOPT) = '4';
295 |         WkCmd    = 'ENDJOB JOB(' + WkQualJob +
296 |                    ') OPTION(*CNTRLD) DELAY(30) DUPJOBOPT(*MSG)';
297 |         WkCmdLen = %len(WkCmd);
298 |         monitor;
299 |           QCMDEXC(WkCmd: WkCmdLen);
300 |           WkMsgText = 'End (Ctrl) submitted: ' + WkQualJob;
301 |           exsr SendMsgText;
302 |         on-error;
303 |           WkMsgText = 'End (Ctrl) failed: ' + WkQualJob + '. Check job log.';
304 |           exsr SendMsgText;
305 |         endmon;
306 | 
307 |       // 5 = Display Messages (WRKJOB OPTION(*MSG) opens the job message queue)
308 |       when %trim(SFOPT) = '5';
309 |         WkCmd    = 'WRKJOB JOB(' + WkQualJob + ') OPTION(*MSG)';
310 |         WkCmdLen = %len(WkCmd);
311 |         QCMDEXC(WkCmd: WkCmdLen);
312 | 
313 |       // 6 = Release Job
314 |       when %trim(SFOPT) = '6';
315 |         WkCmd    = 'RLSJOB JOB(' + WkQualJob + ') DUPJOBOPT(*MSG)';
316 |         WkCmdLen = %len(WkCmd);
317 |         monitor;
318 |           QCMDEXC(WkCmd: WkCmdLen);
319 |           WkMsgText = 'Release submitted: ' + WkQualJob;
320 |           exsr SendMsgText;
321 |         on-error;
322 |           WkMsgText = 'Release failed: ' + WkQualJob + '. Check job log.';
323 |           exsr SendMsgText;
324 |         endmon;
325 | 
326 |       // 7 = Display Job Log
327 |       when %trim(SFOPT) = '7';
328 |         WkCmd    = 'DSPJOBLOG JOB(' + WkQualJob + ') OUTPUT(*)';
329 |         WkCmdLen = %len(WkCmd);
330 |         QCMDEXC(WkCmd: WkCmdLen);
331 | 
332 |       // 8 = End Job (Immediate)
333 |       when %trim(SFOPT) = '8';
334 |         WkCmd    = 'ENDJOB JOB(' + WkQualJob +
335 |                    ') OPTION(*IMMED) DUPJOBOPT(*MSG)';
336 |         WkCmdLen = %len(WkCmd);
337 |         monitor;
338 |           QCMDEXC(WkCmd: WkCmdLen);
339 |           WkMsgText = 'End (Immed) submitted: ' + WkQualJob;
340 |           exsr SendMsgText;
341 |         on-error;
342 |           WkMsgText = 'End (Immed) failed: ' + WkQualJob + '. Check job log.';
343 |           exsr SendMsgText;
344 |         endmon;
345 | 
346 |       other;
347 |         WkMsgText = 'Option "' + %trimr(SFOPT) + '" not valid. Use 2-8.';
348 |         exsr SendMsgText;
349 | 
350 |     endsl;
351 | 
352 |     SFOPT = '   ';
353 |     update MSGSFL;
354 | 
355 |     readc MSGSFL;
356 |     WkEof = %eof(MSGWDSPF);
357 | 
358 |   enddo;
359 | 
360 | endsr;
361 | 
362 | // ============================================================================
363 | // Subroutine: SendMsgText
364 | // ============================================================================
365 | begsr SendMsgText;
366 | 
367 |   MsgClr = *on;
368 |   write MSGQCTL;
369 |   MsgClr = *off;
370 | 
371 |   SendPgmMsg(
372 |     NullBuf :
373 |     '                    ' :
374 |     %char(WkMsgText) :
375 |     %len(%trimr(WkMsgText)) :
376 |     '*INFO     ' :
377 |     '*EXT      ' :
378 |     0 :
379 |     MsgKey :
380 |     ErrCode
381 |   );
382 | 
383 |   MsgDsp = *on;
384 |   write MSGQCTL;
385 | 
386 | endsr;
387 |
